    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xFDA6CA30CA4360ABULL + 0xE5F088F724A3F253ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xFE79006CFFA1BE45ULL + 0xD55DC7FA38BF3A12ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xAB26FFC94C5EEB6FULL + 0xD1E24334FF02B98FULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseB(pNonce * 0xF3BB087AE7F89E77ULL + 0xEE7F584E8CFE899AULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xA788235E18D1D65BULL + 0xE2DD6DA72EFC0CE9ULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0xA342C968F2C579C1ULL + 0xA5611B034A1B2672ULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0x8BCFC4C594B6B891ULL + 0x8B3D1462F938FE26ULL);
    const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0xF01B64842E582069ULL + 0xB43B4CC45355F203ULL);
