            aWandererH = aWandererH + (((RotL64(aScatter, 37U) + aOrbiterG) + RotL64(aOrbiterE, 47U)) + aWUSaltH[(((511U - aIndex) + 305U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 19U) + RotL64(aOrbiterD, 5U)) + aOrbiterG);
            aWandererK = aWandererK + ((RotL64(aCross, 50U) + RotL64(aOrbiterF, 53U)) + aOrbiterD);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 35U) + RotL64(aOrbiterK, 35U)) + aOrbiterH);
