            aIngress = (RotL64(aAetherLaneD[((aIndex + 4170U)) & S_BLOCK1], 19U) ^ RotL64(aAetherLaneB[((aIndex + 3618U)) & S_BLOCK1], 57U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 6841U)) & W_KEY1], 46U) ^ RotL64(aPlasmaLaneD[((aIndex + 7692U)) & S_BLOCK1], 3U));
