            aOrbiterD = (((aWandererA + RotL64(aCross, 39U)) + RotL64(aCarry, 21U)) + 0xAB979513A8E774AEULL) + aOASaltF[((aIndex + 194U)) & S_SALT1];
            aOrbiterC = (aWandererB + RotL64(aIngress, 27U)) + 0x92ADD56B2A49AAD8ULL;
