            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xDA4CD9DE4B1C28A7ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x0DE44E4A8A33C19BULL), 13U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterJ) + 0xB176704E0C6440D2ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x8FE85FC1545425F3ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xEF1E61FC1BDEE865ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x2CDC26AD7ED3AB33ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xF7AD03378E93489CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4D572925B522CC55ULL), 5U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0xCE62D50CD71747F0ULL) + aOUSaltH[((aIndex + 243U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x25EF54E21013934DULL) ^ aOUSaltB[(((511U - aIndex) + 55U)) & S_SALT1];
