            aWandererK = aWandererK + ((RotL64(aCross, 41U) + aOrbiterC) + RotL64(aOrbiterA, 23U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 44U) + aOrbiterJ) + RotL64(aOrbiterK, 5U));
