            aWandererF = aWandererF ^ (((RotL64(aPrevious, 19U) + aOrbiterK) + RotL64(aOrbiterC, 51U)) + aWUSaltH[(((511U - aIndex) + 241U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 23U) + aOrbiterB) + RotL64(aOrbiterF, 57U)) + aWUSaltB[((aIndex + 417U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aIngress, 3U) + aOrbiterI) + RotL64(aOrbiterB, 26U)) + RotL64(aCarry, 29U));
            aWandererJ = aWandererJ + ((RotL64(aScatter, 11U) + aOrbiterD) + RotL64(aOrbiterH, 53U));
            //
