            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateBDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 54U) + RotL64(aCross, 19U)) ^ (RotL64(aCarry, 37U) ^ RotL64(aIngress, 3U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterC = (aWandererG + RotL64(aScatter, 19U)) + 0x84C4175E67AD49CDULL;
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 29U)) + RotL64(aCarry, 29U)) + 0xC95DEDB11D3AD7D7ULL;
            aOrbiterH = ((aWandererK + RotL64(aCross, 34U)) + 0x8EB5F7CEC9FC9026ULL) + aOASaltH[(((511U - aIndex) + 29U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aIngress, 23U)) + 0x8794B81CA02FD1E3ULL;
            aOrbiterK = ((aWandererI + RotL64(aScatter, 27U)) + RotL64(aCarry, 11U)) + 0x0436F963C9876D33ULL;
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 13U)) + 0x44B22B5D7BCB8897ULL) + aOASaltG[((aIndex + 93U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aCross, 56U)) + 0x633DE15BB920868CULL;
            aOrbiterE = (aWandererC + RotL64(aIngress, 39U)) + 0x5167BE357D6D4BD5ULL;
            aOrbiterI = (((aWandererA + RotL64(aScatter, 5U)) + RotL64(aCarry, 47U)) + 0xDA2F96AC98126C50ULL) + aOASaltE[((aIndex + 407U)) & S_SALT1];
            aOrbiterB = (aWandererF + RotL64(aPrevious, 11U)) + 0x554C37D42DAB20EEULL;
            aOrbiterD = (aWandererJ + RotL64(aCross, 51U)) + 0x999761F809A6E23EULL;
